import { z } from "zod";
import { auth } from "@/auth";
import { dismissAccountNotice } from "@/lib/account-notices";

export async function POST(request: Request) {
  const headers = { "Cache-Control": "private, no-store" };
  const session = await auth();
  if (!session?.user?.id)
    return Response.json({ error: "Sign in first." }, { status: 401, headers });
  const body = z
    .object({ noticeId: z.uuid() })
    .strict()
    .safeParse(await request.json().catch(() => null));
  if (!body.success)
    return Response.json(
      { error: "Choose a valid notice." },
      { status: 400, headers },
    );
  await dismissAccountNotice(session.user.id, body.data.noticeId);
  return Response.json({ dismissed: true }, { headers });
}
